                  <CardHeader><CardTitle>${task.titulo}</CardTitle><CardDescription>${this.msg[STATUS_KEY[task.status]]} · ${this.msg[PRIORITY_KEY[task.prioridade]]}</CardDescription></CardHeader>
                  <CardContent><span class="rounded-full bg-[var(--status-info-bg,transparent)] px-2 py-1 text-xs text-[var(--status-info-text,currentColor)]">${task.listaTarefas.nome}</span></CardContent>
