                </section>
              </section>

              <section class="mt-5 border-t border-[var(--border-subtle,currentColor)] pt-4" data-organism-id="tarefaAcoes">
                ${task.details.aberta ? html`
                  ${this.trocarResponsavelTarefaError || this.cancelarTarefaEquipeError ? html`<p class="mb-3 text-sm text-[var(--status-error-text,currentColor)]">${this.msg.actionError}</p>` : ''}
                  <form @submit=${(e: SubmitEvent) => { e.preventDefault(); this.trocarResponsavelTarefa(); }}>
                    <groupselectone--ml-select-one-autocomplete .value=${draft.responsavelId} name="novoResponsavel" placeholder=${this.msg.chooseAssignee} ?loading=${this.buscarResponsaveisDisponiveisStatus === 'loading'} @focus=${() => this.buscarResponsaveisDisponiveis()} @change=${(e: CustomEvent<{ value: string | null }>) => this.setTrocarResponsavelTarefaDraft({ responsavelId: e.detail.value })}>
