                  </form>
                ` : html`<p class="text-sm text-[var(--text-muted,currentColor)]">${this.msg.taskClosed}</p>`}
              </section>

              <section class="mt-5 border-t border-[var(--border-subtle,currentColor)] pt-4" data-organism-id="tarefaHistorico">
